impl<T: gx::Coef> Plane<(), T> {
    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(e1: T, e2: T, e3: T, e0: T) -> Self {
        Plane { c: [e1, e2, e3, e0] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
    #[inline(always)]
    pub fn prepare<X>(self) -> <Self as gx::Prepare<X>>::Output
    where
        Self: gx::Prepare<X>,
    {
        gx::Prepare::prepare(self)
    }

    /// The identity map on `Plane`: a `Plane` with one open `Plane` slot.
    #[inline(always)]
    pub fn slot() -> Plane<(Plane,), T> {
        Plane { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e1`.
    #[inline(always)]
    pub fn e1(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e2`.
    #[inline(always)]
    pub fn e2(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e3`.
    #[inline(always)]
    pub fn e3(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e0`.
    #[inline(always)]
    pub fn e0(&self) -> T {
        self.c[3]
    }
}

