impl<T: gx::Coef> Point<(), T> {
    /// A value from its coefficients, in blade order.
    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(e032: T, e013: T, e021: T, e123: T) -> Self {
        Point { c: [e032, e013, e021, e123] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
    #[inline(always)]
    pub fn prepare<X>(self) -> <Self as gx::Prepare<X>>::Output
    where
        Self: gx::Prepare<X>,
    {
        gx::Prepare::prepare(self)
    }

    /// The identity map on `Point`: a `Point` with one open `Point` slot.
    #[inline(always)]
    pub fn slot() -> Point<(Point,), T> {
        Point { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `e032`.
    #[inline(always)]
    pub fn e032(&self) -> T {
        self.c[0]
    }

    /// Coefficient of `e013`.
    #[inline(always)]
    pub fn e013(&self) -> T {
        self.c[1]
    }

    /// Coefficient of `e021`.
    #[inline(always)]
    pub fn e021(&self) -> T {
        self.c[2]
    }

    /// Coefficient of `e123`.
    #[inline(always)]
    pub fn e123(&self) -> T {
        self.c[3]
    }
}

