impl<T: gx::Real> Point<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[3] * x[3];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (8 mul, 0 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Point<(), T> {
        let x = self.c;
        let t0 = x[3] * x[3];
        let t1 = x[3] * t0;
        let t2 = x[3] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = -t5;
        let t10 = -t6;
        let t11 = -t7;
        let t12 = -t8;
        Point::from_coeffs([t9, t10, t11, t12])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[3] * x[3];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Point::from_coeffs([t0, t1, t2, t3]))
    }

}

#[doc = "The pseudoscalar `e0123`."]
///
/// Blades, in coefficient order: `[e0123]`.
///
/// `S` lists the open slots: `Pseudoscalar` (that is, `Pseudoscalar<()>`) is a value, `Pseudoscalar<(A,)>` a
/// linear map from `A`, `Pseudoscalar<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Pseudoscalar<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 1],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Pseudoscalar<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Pseudoscalar<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Pseudoscalar<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Pseudoscalar<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Pseudoscalar");
        for (b, c) in <Pseudoscalar as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Pseudoscalar {
    const N: usize = 1;
    const NAME: &'static str = "Pseudoscalar";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e0123"];
    type Arr<X: gx::Elem> = [X; 1];
    type Mv<S: gx::Slots, T: gx::Coef> = Pseudoscalar<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 1] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 1], f: impl FnMut(&X) -> Y) -> [Y; 1] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 1],
        b: &[Y; 1],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 1] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

