impl<T: gx::Real> Translator<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        t0
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (8 mul, 0 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Translator<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t0 * t3;
        let t5 = x[0] * t4;
        let t6 = x[1] * t4;
        let t7 = x[2] * t4;
        let t8 = x[3] * t4;
        let t9 = -t6;
        let t10 = -t7;
        let t11 = -t8;
        Translator::from_coeffs([t5, t9, t10, t11])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let s0 = (p0).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Translator::from_coeffs([t0, t1, t2, t3]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Translator::from_coeffs(c).normalized()
    }

}

impl<T: gx::Real> gx::Log<Line<(), T>> for gx::Unit<Translator<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Line<(), T> {
        let x = self.into_inner().c;
        let [h0, h1] = gx::study::log_coeffs(-1, (x[0], T::from_i64(0)), (T::from_i64(0), T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Line::from_coeffs([T::from_i64(0), T::from_i64(0), T::from_i64(0), t0, t1, t2])
    }
}

#[doc = "A rigid motion: the even subalgebra."]
///
/// Blades, in coefficient order: `[1, e23, e31, e12, e01, e02, e03, e0123]`.
///
/// `S` lists the open slots: `Motor` (that is, `Motor<()>`) is a value, `Motor<(A,)>` a
/// linear map from `A`, `Motor<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Motor<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 8],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Motor<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Motor<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Motor<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Motor<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Motor");
        for (b, c) in <Motor as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Motor {
    const N: usize = 8;
    const NAME: &'static str = "Motor";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e23", "e31", "e12", "e01", "e02", "e03", "e0123"];
    type Arr<X: gx::Elem> = [X; 8];
    type Mv<S: gx::Slots, T: gx::Coef> = Motor<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 8] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 8], f: impl FnMut(&X) -> Y) -> [Y; 8] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 8],
        b: &[Y; 8],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 8] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

