impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[2] * x[2];
        let t3 = x[4] * x[4];
        let t5 = x[9] * x[9];
        let t7 = x[14] * x[14];
        let t8 = x[0].mul_add(x[0], t1);
        let t9 = x[3].mul_add(x[3], t3);
        let t10 = t8 + t9;
        let t11 = x[8].mul_add(x[8], t5);
        let t12 = x[10].mul_add(x[10], t7);
        let t13 = t11 + t12;
        let t14 = t10 + t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

