impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Scalar<S2, T>> for Scalar<S1, T> {
    type Output = Scalar<gx::Cat<S1, S2>, T>;
    #[inline(always)]
    fn gp(self, rhs: Scalar<S2, T>) -> Scalar<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Scalar {
            c: [
                (a[0] * b[0]).0,
            ],
        }
    }
}

impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Plane<S2, T>> for Scalar<S1, T> {
    type Output = Plane<gx::Cat<S1, S2>, T>;
    #[inline(always)]
    fn gp(self, rhs: Plane<S2, T>) -> Plane<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        Plane {
            c: [
                (a[0] * b[0]).0,
                (a[0] * b[1]).0,
                (a[0] * b[2]).0,
                (a[0] * b[3]).0,
            ],
        }
    }
}

